if isinstance(data, dict):
    print('keys', list(data.keys()))
    for k,v in data.items():
        if isinstance(v, (dict, list)):
            print(k, type(v).__name__, (len(v) if hasattr(v,'__len__') else ''))
        else:
            print(k, type(v).__name__, str(v)[:200])
"

