                }
                $cell = $row[2];
40→                $table[$row[1]] = [
                    'status' => str_starts_with($cell, 'Build') ? 'build' : 'exists',
                    'owner_phase' => preg_match_all('/P\d+/', $cell, $phases) > 0 ? end($phases[0]) : null,
                ];
            }
        }
    }

    return $table;
}
