            ->and(array_keys($entry))->toBe(['id', 'status', 'checks', 'blocking', 'owner_phase'])
            ->and($entry['status'])->toBeIn(['exists', 'build'])
            ->and($entry['blocking'])->toMatch('/\A(?:now|after P[1-4])\z/')
            ->and($entry['owner_phase'])->toBeIn([null, 'P1', 'P2', 'P3', 'P4'])
