        'I2' => __DIR__.'/Allowlists/i2.json', 'I3' => __DIR__.'/Allowlists/i3.json', 'I4' => __DIR__.'/Allowlists/i4.json', 'I5' => __DIR__.'/Allowlists/i5.json',
