                $adapter?->isMember(subject: $subject, tenant: $tenant);
                $adapter->isMember(format(value: 1), [$tenant, 'key' => 1]);
                $adapter->isMember($subject ? A : B, $tenant);
                $adapter->other(subject: $subject);
